export function get(category, iconName) {
  if (!ICONS_LIST[category] || !ICONS_LIST[category][iconName]) {
    console.warn(`[IconsManager] Unknown icon requested: category="${category}", iconName="${iconName}"`);
    const iconContainer = document.createElement('span');
    iconContainer.classList.add('icon-container');
    iconContainer.innerHTML = '<svg width="16" height="16" viewBox="0 0 16 16"></svg>';
    return iconContainer;
  }

  const iconContainer = document.createElement('span');
  iconContainer.classList.add('icon-container');
  iconContainer.innerHTML = ICONS_LIST[category][iconName];
  return iconContainer;
}